// The artifacts of the openbao example, generated by the TypeScript SDK, are the ones the Go example generates
// (examples/openbao/golden, written by `go test ./examples/openbao/go`).
//
//     node --test openbao.test.ts

import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

import { generate } from "../../../sdk/ts/src/index.ts";
import { OpenBao } from "./openbao.ts";

const GOLDEN = join(dirname(fileURLToPath(import.meta.url)), "..", "golden");

function tree(d: string): string[] {
  const out: string[] = [];
  const walk = (dir: string) => {
    for (const e of readdirSync(dir, { withFileTypes: true })) {
      const p = join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (statSync(p).isFile()) out.push(relative(d, p).split(sep).join("/"));
    }
  };
  walk(d);
  return out.sort();
}

test("the artifacts equal the Go example's", () => {
  const out = mkdtempSync(join(tmpdir(), "packsdk-"));
  try {
    generate(out, new OpenBao());
    assert.deepEqual(tree(GOLDEN), tree(out));
    for (const rel of tree(GOLDEN)) {
      const want = readFileSync(join(GOLDEN, rel));
      const got = readFileSync(join(out, rel));
      if (rel.endsWith(".json")) { // the same document; the order of keys is each SDK's
        assert.deepEqual(JSON.parse(got.toString()), JSON.parse(want.toString()), rel);
      } else {
        assert.equal(got.toString(), want.toString(), rel);
      }
    }
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
});

// The CEL the pack speaks: the declaration in TypeScript is the one the Go render evaluates.
test("the formula", () => {
  const formulas = new OpenBao().packCompute();
  assert.deepEqual(["/openbao/storage"], Object.keys(formulas));
  const expr = formulas["/openbao/storage"];
  for (const want of ["has(pack.values.postgres)", "'postgresql'", "connection_url", "${secret:",
                      "pack.keys.postgres.instances[0]", "ports.pg", "pack.values.postgres.database"]) {
    assert.ok(expr.includes(want), want);
  }
});

test("the rule", () => {
  const rules = new OpenBao().packRules();
  assert.deepEqual(["/openbao/storage"], Object.keys(rules));
  const [rule] = rules["/openbao/storage"];
  assert.equal(
    rule.rule,
    "!has(pack.values.postgres) || !has(values.openbao.storage) || size(values.openbao.storage) == 0");
  assert.ok(rule.message);
});

test("the schema carries them", () => {
  const pack = new OpenBao();
  const out = mkdtempSync(join(tmpdir(), "packsdk-"));
  try {
    generate(out, pack);
    const s = JSON.parse(readFileSync(join(out, "openbao", "schema.json")).toString());
    const storage = s.properties.openbao.properties.storage;
    assert.equal(pack.packCompute()["/openbao/storage"], storage["x-pack-compute"]);
    // the rule as written, and its message in the other languages of docs/
    const written = storage["x-pack-rules"].map(({ "x-pack-i18n": _, ...r }: Record<string, unknown>) => r);
    assert.deepEqual(pack.packRules()["/openbao/storage"], written);
    const [rule] = storage["x-pack-rules"];
    assert.ok(!("phases" in rule));
    assert.ok("ru" in rule["x-pack-i18n"]);
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
});
